package com.quantaedge.api;
import static org.junit.jupiter.api.Assertions.assertEquals;import static org.junit.jupiter.api.Assertions.assertThrows;import static org.mockito.ArgumentMatchers.any;import static org.mockito.ArgumentMatchers.anyString;import static org.mockito.ArgumentMatchers.eq;import static org.mockito.Mockito.never;import static org.mockito.Mockito.verify;import static org.mockito.Mockito.verifyNoInteractions;import static org.mockito.Mockito.when;
import java.util.List;import java.util.Map;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;
@ExtendWith(MockitoExtension.class) class HrAttendanceLeaveControllerTest{
 @Mock JdbcTemplate jdbc;@Mock AuthorizationService authorization;@Mock StaffAuditService audit;HrAttendanceLeaveController controller;final AuthContext manager=new AuthContext(100L,null,77L,"HR_MANAGER","HR manager");
 @BeforeEach void setup(){controller=new HrAttendanceLeaveController(jdbc,authorization,audit);}
 @Test void workScheduleRejectsUnsupportedWorkingWeek(){when(authorization.requirePermission(manager,"HR_EMPLOYEE_MANAGE")).thenReturn(manager);ResponseStatusException ex=assertThrows(ResponseStatusException.class,()->new HrEmployeeController(jdbc,authorization,audit).updateWorkSchedule(1,Map.of("workingDaysPerWeek",7),manager));assertEquals(400,ex.getStatusCode().value());verifyNoInteractions(jdbc);}
 @Test void holidayViewRequiresPermissionBeforeDatabase(){when(authorization.requirePermission(manager,"HR_HOLIDAY_VIEW")).thenThrow(new SecurityException("denied"));assertThrows(SecurityException.class,()->new HrHolidayController(jdbc,authorization,audit).list(1,null,null,true,manager));verifyNoInteractions(jdbc,audit);}
 @Test void attendanceViewRequiresPermissionBeforeDatabase(){when(authorization.requirePermission(manager,"HR_ATTENDANCE_VIEW")).thenThrow(new SecurityException("denied"));assertThrows(SecurityException.class,()->controller.attendance(manager,null,null,null,0,100));verifyNoInteractions(jdbc,audit);}
 @Test void attendanceWriteRequiresPermissionBeforeDatabase(){when(authorization.requirePermission(manager,"HR_ATTENDANCE_MANAGE")).thenThrow(new SecurityException("denied"));assertThrows(SecurityException.class,()->controller.saveAttendance(1,"2026-10-12",Map.of("status","PRESENT"),manager));verifyNoInteractions(jdbc,audit);}
 @Test void correctingExistingAttendanceRequiresReasonBeforeWritingHistory(){when(authorization.requirePermission(manager,"HR_ATTENDANCE_MANAGE")).thenReturn(manager);when(jdbc.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(Map.of("id",9L,"organization_id",1L,"employee_number","QE-EMP-000009","display_name","A Teacher","employment_status","ACTIVE")),List.of(Map.of("id",71L,"attendance_status","PRESENT")));ResponseStatusException ex=assertThrows(ResponseStatusException.class,()->controller.saveAttendance(9,"2026-10-12",Map.of("status","ABSENT"),manager));assertEquals(400,ex.getStatusCode().value());verify(jdbc,never()).update(anyString(),any(Object[].class));verify(jdbc,never()).queryForObject(anyString(),eq(Long.class),any(Object[].class));verify(audit,never()).recordAction(any(),anyString(),anyString());}
 @Test void correctionHistoryReadRequiresAttendanceViewPermission(){when(authorization.requirePermission(manager,"HR_ATTENDANCE_VIEW")).thenThrow(new SecurityException("denied"));assertThrows(SecurityException.class,()->controller.attendanceCorrections(9,"2026-10-12",manager));verifyNoInteractions(jdbc,audit);}
 @Test void invalidAttendanceStatusIsRejectedBeforeEmployeeLookup(){when(authorization.requirePermission(manager,"HR_ATTENDANCE_MANAGE")).thenReturn(manager);ResponseStatusException ex=assertThrows(ResponseStatusException.class,()->controller.saveAttendance(1,"2026-10-12",Map.of("status","WORK_FROM_MARS"),manager));assertEquals(400,ex.getStatusCode().value());verify(jdbc,never()).queryForList(anyString(),any(Object[].class));verify(audit,never()).recordAction(any(),anyString(),anyString());}
 @Test void leaveRegisterRequiresPermissionBeforeDatabase(){when(authorization.requirePermission(manager,"HR_LEAVE_VIEW")).thenThrow(new SecurityException("denied"));assertThrows(SecurityException.class,()->controller.leaves(manager,"ALL",null,0,100));verifyNoInteractions(jdbc,audit);}
 @Test void leaveDecisionRejectsUnsupportedTransition(){when(authorization.requirePermission(manager,"HR_LEAVE_MANAGE")).thenReturn(manager);when(jdbc.queryForList(anyString(),eq(44L))).thenReturn(List.of(Map.of("id",44L,"employee_id",9L,"request_status","PENDING")));ResponseStatusException ex=assertThrows(ResponseStatusException.class,()->controller.decide(44,Map.of("status","CANCELLED"),manager));assertEquals(400,ex.getStatusCode().value());verify(jdbc,never()).update(anyString(),any(Object[].class));verify(audit,never()).recordAction(any(),anyString(),anyString());}
 @Test void invertedLeaveDatesAreRejectedBeforeInsert(){when(authorization.requirePermission(manager,"HR_LEAVE_MANAGE")).thenReturn(manager);when(jdbc.queryForList(anyString(),eq(9L))).thenReturn(List.of(Map.of("id",9L,"organization_id",1L,"employee_number","QE-EMP-000009","display_name","A Teacher","employment_status","ACTIVE")));when(jdbc.queryForObject(anyString(),eq(Boolean.class),any(Object[].class))).thenReturn(true);ResponseStatusException ex=assertThrows(ResponseStatusException.class,()->controller.createLeave(Map.of("employeeId",9,"leaveTypeCode","CASUAL","startDate","2026-10-13","endDate","2026-10-12","reason","Personal work"),manager));assertEquals(400,ex.getStatusCode().value());verify(jdbc,never()).update(anyString(),any(Object[].class));verify(audit,never()).recordAction(any(),anyString(),anyString());}
}